options.afterRender:
// Place line above the table.
const root = context.element.querySelector('.h360-top');
if (!root) { return; }
const series = (context.panelData && context.panelData.series) || [];
const frame = series.find((s) => s.refId === 'A') || series[0];
const a = {};
if (frame) { frame.fields.forEach((f) => { a[f.name] = Array.from(f.values)[0]; }); }
const esc = (v) => String(v == null ? '' : v).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
if (!frame) { root.innerHTML = ''; return; }
const rv = context.grafana && context.grafana.replaceVariables;
// Team names, as plain text (the variable holds styled spans).
const teams = rv ? String(rv('${requiredGroups}')).replace(/<[^>]*>/g, '').trim() : '';
if (String(a.isAllowed) !== '1') {
  root.innerHTML = '<div class="ovq-warn"><span>⚠️</span><span><strong>Access Denied:</strong> Ask admin to add to one of these teams: '
    + esc(teams) + '</span></div>';
  return;
}
const chip = (cls, text) => '<span class="h360-key"><i class="' + cls + '"></i>' + text + '</span>';
root.innerHTML = '<div class="h360-place"><strong>' + esc(a.place) + '</strong>'
  + (a.month_label ? ' · ' + esc(a.month_label) : '')
  + (a.coverage ? ' · ' + esc(a.coverage) : '') + '</div>'
  + '<div class="h360-legend">Days of medicine left for the patients: '
  + chip('r', 'under 30') + chip('o', '30–59') + chip('y', '60–89') + chip('g', '90 or more')
  + chip('q', '? not reported') + '</div>';

