options.afterRender:
// A Viewer who opens the board with no place goes to their home unit (UX-02), the unit the
// home page links to. 0 is All Locations and stays. Elsewhere this shows a My place link.
const root = context.element.querySelector('.h360-home');
if (!root) { return; }
const series = (context.panelData && context.panelData.series) || [];
const frame = series[0];
const field = frame && frame.fields.find((f) => f.name === 'home_unit');
const home = String((field && Array.from(field.values)[0]) || '').trim();
const g = context.grafana || {};
const vars = (t) => (typeof g.replaceVariables === 'function' ? String(g.replaceVariables(t)).trim() : '');
const org = vars('${org_unit}');

// The Enter stock link adds ?enter=1: bring the form into view. This panel is at the top, so it
// is always drawn; the form panel lower down is drawn only once it is near the screen.
const nav = (window.__h360StockNav = window.__h360StockNav || {});
const toForm = () => {
  const el = document.querySelector('[data-viz-panel-key="panel-12"]');
  if (el) { el.scrollIntoView({ behavior: 'smooth', block: 'start' }); }
};
// Scroll twice (the table can still grow), then drop enter=1 so later month or place changes stay put.
const goToForm = () => {
  setTimeout(toForm, 400);
  setTimeout(() => {
    toForm();
    if (g.locationService && typeof g.locationService.partial === 'function') { g.locationService.partial({ enter: null }, true); }
  }, 1500);
};
const wantsForm = (loc) => /\/d\/heart360_drug_stock/.test(loc.pathname) && new URLSearchParams(loc.search).get('enter') === '1';
if (wantsForm(location) && nav.done !== location.href) {
  nav.done = location.href;
  goToForm();
}
const hist = g.locationService && typeof g.locationService.getHistory === 'function' ? g.locationService.getHistory() : null;
if (hist && !nav.listening) {
  nav.listening = true;
  hist.listen((loc) => {
    if (wantsForm(loc || location)) { nav.done = location.href; goToForm(); }
  });
}

if (!/^[0-9]{1,9}$/.test(home)) { root.innerHTML = ''; return; }
if (org === '' && g.locationService && typeof g.locationService.partial === 'function') {
  root.innerHTML = '<span class="h360-home-note">Opening your place…</span>';
  g.locationService.partial({ 'var-org_unit': home }, true);
  return;
}
root.innerHTML = org === home ? '' : '<a class="h360-home-link" href="/d/heart360_drug_stock?var-org_unit=' + home
  + '&var-reporting_month=' + encodeURIComponent(vars('${reporting_month}')) + '">My place</a>';

