.h360-home-note { color: #6E6E6E; }

options.afterRender:
// Enter stock form (story 3.5, UX-13). One number per protocol drug and strength for one
// facility and month. Above facility level the user picks the facility here, from the
// stock-form facilities inside the place they can see. Saves to h360-api, which takes identity
// from the Grafana session and checks access again.
const root = context.element.querySelector('.dse');
if (!root) { return; }

const series = (context.panelData && context.panelData.series) || [];
const frame = series.find((s) => s.refId === 'A');
const all = (() => {
  if (!frame) { return []; }
  const cols = frame.fields.map((x) => [x.name, Array.from(x.values)]);
  const n = cols.length ? cols[0][1].length : 0;
  return Array.from({ length: n }, (_, i) => Object.fromEntries(cols.map(([k, v]) => [k, v[i]])));
})();
const flags = all[0] || {};
const rows = all.filter((r) => r.drug_code != null);

const esc = (v) => String(v == null ? '' : v).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const warn = (html) => '<div class="dse-warn"><span>⚠️</span><span>' + html + '</span></div>';
const note = (text) => '<h2 class="dse-title">Enter stock</h2><div class="dse-note">' + esc(text) + '</div>';

const rv = context.grafana && context.grafana.replaceVariables;
// Team names, as plain text (the variable holds styled spans).
const teams = rv ? String(rv('${requiredGroups}')).replace(/<[^>]*>/g, '').trim() : '';
const memo = (window.__h360StockEntry = window.__h360StockEntry || {});

if (Number(flags.isAllowed) !== 1) {
  root.innerHTML = Number(flags.isAll) === 1
    ? note('Pick your facility under Change location to enter stock.')
    : warn('<strong>Access Denied:</strong> Ask admin to add to one of these teams: ' + esc(teams));
  return;
}
if (!rows.length) {
  root.innerHTML = note('Stock is entered for a facility. Pick a facility or district under Change location.');
  return;
}

const MAX = 1000000;
const facilities = [...new Map(rows.map((r) => [Number(r.facility_id), r.facility_name])).entries()];
const months = [...new Map(rows.map((r) => [r.month, r.month_label])).entries()];
const known = (id) => facilities.some(([f]) => f === id);
// Kept across the refresh that follows a save, so the form reopens on the saved facility and month with its note.
const recent = Date.now() - (memo.at || 0) < 8000 && known(memo.org) ? memo : null;
let facility = facilities.length === 1 ? facilities[0][0] : (known(memo.pick) ? memo.pick : null);
let month = (recent && recent.month) || flags.this_month;
if (!months.some(([m]) => m === month)) { month = months[0][0]; }

const fmt = (n) => Number(n).toLocaleString('en-US');
const nameOf = (id) => (facilities.find(([f]) => f === id) || [null, ''])[1];
const cells = () => rows.filter((r) => Number(r.facility_id) === facility && r.month === month);

const render = () => {
  const pick = facilities.length > 1
    ? '<label class="dse-field dse-top-field"><span>Facility</span><select class="dse-facility">'
      + (facility == null ? '<option value="" selected disabled>Choose a facility</option>' : '')
      + facilities.map(([f, name]) => '<option value="' + f + '"' + (f === facility ? ' selected' : '') + '>' + esc(name) + '</option>').join('')
      + '</select></label>'
    : '';
  const head = '<h2 class="dse-title">Enter stock' + (facilities.length === 1 ? ' for ' + esc(facilities[0][1]) : '') + '</h2>'
    + '<div class="dse-head">Count the tablets in stock. Leave blank if not counted. Enter 0 if none.</div>';
  if (facility == null) {
    root.innerHTML = head + '<form class="dse-form" novalidate><div class="dse-tops">' + pick + '</div></form>';
    return;
  }
  const list = cells();
  const last = list.filter((r) => r.saved_on).sort((a, b) => String(b.saved_at).localeCompare(String(a.saved_at)))[0];
  root.innerHTML = head
    + '<form class="dse-form" novalidate><div class="dse-tops">' + pick
    + '<label class="dse-field dse-top-field"><span>Month</span><select class="dse-month">'
    + months.map(([m, label]) => '<option value="' + esc(m) + '"' + (m === month ? ' selected' : '') + '>' + esc(label) + '</option>').join('')
    + '</select></label></div>'
    + '<div class="dse-grid">'
    + list.map((r) => '<label class="dse-field"><span>' + esc(r.drug_label) + '</span>'
      + '<input type="number" inputmode="numeric" min="0" max="' + MAX + '" step="1" placeholder="Not counted"'
      + ' data-code="' + esc(r.drug_code) + '" value="' + (r.in_stock == null ? '' : esc(r.in_stock)) + '"></label>').join('')
    + '</div>'
    + '<div class="dse-actions"><button type="submit" class="dse-save">Save stock</button>'
    + '<span class="dse-msg" aria-live="polite"></span></div>'
    + '<div class="dse-last">' + (last ? 'Last saved ' + esc(last.saved_on) + (last.saved_by ? ' by ' + esc(last.saved_by) : '') + '.' : 'Nothing saved for this month yet.') + '</div>'
    + '</form>';
  if (recent && recent.org === facility && recent.month === month && recent.note) { message(recent.note, recent.cls); }
};

const message = (text, cls) => {
  const m = root.querySelector('.dse-msg');
  if (m) { m.className = 'dse-msg ' + (cls || ''); m.textContent = text; }
};

// --- Saving: posted to h360-api, which takes identity from the Grafana session.
// Set by chat-widget.js; the same Grafana port + 5090 rule when the widget is not loaded.
const H360_API = window.H360_API || (location.protocol + '//' + location.hostname + ':' + ((Number(location.port) || 80) + 5090));
const save = async (orgId, entries) => {
  const body = JSON.stringify({ org_unit_id: orgId, month, entries });
  const res = await fetch(H360_API + '/write/drug-stock', {method:'POST', credentials:'include', headers:{'Content-Type':'application/json','X-H360-Request':'1'}, body});
  const saved = await res.json().catch(() => ({}));
  if (!res.ok || saved.ok === false) {
    const err = new Error(saved.message || res.statusText);
    err.status = res.status;
    throw err;
  }
  return saved;
};

const plain = (err, place) => {
  if (err.status === 403) { return 'Not saved. You do not have access to enter stock for ' + place + '. Ask your admin.'; }
  if (err.status === 401) { return 'Not saved. Sign in again, then save once more.'; }
  if (!err.status) { return 'Not saved. Could not reach the server. Check the connection and try again.'; }
  return 'Not saved. ' + (err.message || 'Try again.');
};

const refreshBoard = () => {
  const g = context.grafana || {};
  const shown = typeof g.replaceVariables === 'function' ? g.replaceVariables('${reporting_month}') : '';
  if (shown !== month && g.locationService && typeof g.locationService.partial === 'function') {
    g.locationService.partial({ 'var-reporting_month': month }, true);
  } else if (typeof g.refresh === 'function') {
    g.refresh();
  }
};

root.addEventListener('change', (e) => {
  if (e.target.classList.contains('dse-month')) { month = e.target.value; render(); }
  if (e.target.classList.contains('dse-facility')) {
    facility = Number(e.target.value);
    memo.pick = facility;
    render();
  }
});

root.addEventListener('input', (e) => {
  if (e.target.dataset.code) { e.target.classList.remove('bad'); message(''); }
});

root.addEventListener('submit', async (e) => {
  e.preventDefault();
  if (facility == null) { return; }
  const inputs = Array.from(root.querySelectorAll('input[data-code]'));
  let bad = false;
  const entries = inputs.map((el) => {
    const raw = el.value.trim();
    // A number input reports '' for text it cannot parse; validity tells that apart from blank.
    const blank = raw === '' && !(el.validity && el.validity.badInput);
    const ok = blank || (/^\d+$/.test(raw) && Number(raw) <= MAX);
    el.classList.toggle('bad', !ok);
    if (!ok) { bad = true; }
    return { drug_code: el.dataset.code, stock: blank ? null : Number(raw) };
  });
  if (bad) { message('Use whole numbers from 0 to ' + fmt(MAX) + ', or leave blank.', 'err'); return; }

  // The select's value is what is saved, so a changed option is checked by the API, not trusted here.
  const sel = root.querySelector('.dse-facility');
  const orgId = sel ? Number(sel.value) : facility;
  const place = sel && sel.selectedOptions[0] ? sel.selectedOptions[0].textContent : nameOf(facility);
  const btn = root.querySelector('.dse-save');
  btn.disabled = true;
  message('Saving…');
  try {
    const saved = await save(orgId, entries);
    const kept = Number(saved.kept_newer || 0);
    const done = 'Saved ✓ ' + place + ', ' + (months.find(([m]) => m === month) || ['', month])[1] + '.';
    const msg = done + (kept ? ' A newer count is kept for ' + kept + (kept === 1 ? ' medicine.' : ' medicines.') : '');
    entries.forEach((en) => {
      const r = cells().find((x) => x.drug_code === en.drug_code);
      if (r && !kept) { r.in_stock = en.stock; }
    });
    Object.assign(memo, { org: facility, pick: facility, month, note: msg, cls: 'ok', at: Date.now() });
    message(msg, 'ok');
    refreshBoard();
  } catch (err) {
    message(plain(err, place), 'err');
    if (context.grafana && context.grafana.notifyError) { context.grafana.notifyError(["Stock not saved", plain(err, place)]); }
  } finally {
    btn.disabled = false;
  }
});

render();

